#!/bin/bash

# Prints the multiplayer test as one Rust file (test.sh writes it to
# tests/multiplayer.rs). Written test-first: it fails until a build or app
# script (*.sh in the repo root or src/) references ORC_WS, the variable for
# orc's websocket library, the way orc-env.sh sets ORC_ANIMATE today.
#
# It's a plain search, not a websocket test. It reads the scripts when the
# test runs, so it doesn't need regenerating after a script changes.

cat << 'EOF'
// Code generated by tests/multiplayer.test.sh. DO NOT EDIT.

use std::fs;
use std::path::Path;

// *.sh files in dir that mention ORC_WS
fn scripts_using_orc_ws(dir: &Path) -> Vec<String> {
    let mut found = vec![];
    for entry in fs::read_dir(dir).expect("read the scripts' directory") {
        let path = entry.expect("read a directory entry").path();
        if path.extension().is_some_and(|ext| ext == "sh") {
            let text = fs::read_to_string(&path).unwrap_or_default();
            if text.contains("ORC_WS") {
                found.push(path.display().to_string());
            }
        }
    }
    found
}

#[test]
fn a_script_uses_orc_websockets() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let mut found = scripts_using_orc_ws(root);
    found.extend(scripts_using_orc_ws(&root.join("src")));
    assert!(
        !found.is_empty(),
        "no *.sh in the repo root or src/ references ORC_WS (orc's websocket library)"
    );
}
EOF
